package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type AmtRec struct { // 01 AMT-REC, 11 bytes
	ArAcct string // PIC X(4) @0 len=4
	ArAmt  decimal.Decimal // PIC 9(5)V99 @4 len=7
}

// Standalone working-storage items
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsBigTotal decimal.Decimal = decimal.Zero // PIC 9(7)V99
var WsWrapTotal decimal.Decimal = decimal.Zero // PIC 9(5)V99
var WsSafeTotal decimal.Decimal = decimal.Zero // PIC 9(5)V99
var WsOverflows int64 = 0 // PIC 99
var WsCount int64 = 0 // PIC 99
var WsHalf decimal.Decimal = decimal.Zero // PIC 9(5)V9
var WsAmtEd string // PIC ZZ,ZZ9.99 len=9
var WsWrapEd string // PIC ZZ,ZZ9.99 len=9
var WsSafeEd string // PIC ZZ,ZZ9.99 len=9
var WsHalfEd string // PIC ZZ,ZZ9.9 len=8

var AmtRecData AmtRec

var amtFile *os.File
var amtScanner *bufio.Scanner

func wrapDecimal(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	vt := v.Truncate(scale)
	scaled := vt.Shift(scale)
	sInt := scaled.IntPart()
	var modBase int64 = 1
	for i := 0; i < intDigits+int(scale); i++ {
		modBase *= 10
	}
	r := sInt % modBase
	return decimal.New(r, -scale)
}

func formatEdited(val decimal.Decimal, pic string) string {
	dot := strings.IndexByte(pic, '.')
	var intPic string
	var fracPic string
	if dot < 0 {
		intPic = pic
		fracPic = ""
	} else {
		intPic = pic[:dot]
		fracPic = pic[dot+1:]
	}
	fracLen := 0
	for _, ch := range fracPic {
		if ch == '9' || ch == 'Z' {
			fracLen++
		}
	}
	intSlots := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intSlots++
		}
	}
	absVal := val.Abs()
	absVal = absVal.Truncate(int32(fracLen))
	scaled := absVal.Shift(int32(fracLen)).Truncate(0)
	sInt := scaled.IntPart()
	var powFrac int64 = 1
	for i := 0; i < fracLen; i++ {
		powFrac *= 10
	}
	var intPart int64
	var fracPart int64
	if fracLen == 0 {
		intPart = sInt
		fracPart = 0
	} else {
		intPart = sInt / powFrac
		fracPart = sInt % powFrac
		if fracPart < 0 {
			fracPart = -fracPart
		}
		if intPart < 0 {
			intPart = -intPart
		}
	}
	var modInt int64 = 1
	for i := 0; i < intSlots; i++ {
		modInt *= 10
	}
	var intPartMod int64
	if modInt != 0 {
		intPartMod = intPart % modInt
	} else {
		intPartMod = intPart
	}
	digits := make([]int, intSlots)
	tmp := intPartMod
	for i := intSlots - 1; i >= 0; i-- {
		digits[i] = int(tmp % 10)
		tmp /= 10
	}
	firstNZ := -1
	for i := 0; i < intSlots; i++ {
		if digits[i] != 0 {
			firstNZ = i
			break
		}
	}
	var sb strings.Builder
	di := 0
	for _, ch := range intPic {
		if ch == ',' {
			if firstNZ == -1 {
				sb.WriteByte(' ')
			} else if firstNZ >= di {
				sb.WriteByte(' ')
			} else {
				sb.WriteByte(',')
			}
		} else if ch == 'Z' || ch == '9' {
			d := digits[di]
			if ch == '9' {
				sb.WriteByte(byte('0' + d))
			} else {
				if firstNZ == -1 {
					sb.WriteByte(' ')
				} else if di < firstNZ {
					sb.WriteByte(' ')
				} else {
					sb.WriteByte(byte('0' + d))
				}
			}
			di++
		} else {
			sb.WriteByte(byte(ch))
		}
	}
	intOut := sb.String()
	if dot < 0 {
		return intOut
	}
	var fracStr string
	if fracLen > 0 {
		fracStr = fmt.Sprintf("%0*d", fracLen, fracPart)
	}
	return intOut + "." + fracStr
}

func computeHalf(amt decimal.Decimal) decimal.Decimal {
	sInt := amt.Shift(2).Truncate(0).IntPart()
	qInt := sInt / 20
	const modBase int64 = 1000000
	r := qInt % modBase
	return decimal.New(r, -1)
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	amtFile = f
	amtScanner = bufio.NewScanner(f)
	// allow long lines
	const maxCap = 1024 * 1024
	buf := make([]byte, 0, 64*1024)
	amtScanner.Buffer(buf, maxCap)
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	amtFile.Close()
	SummaryPara()
}

func ReadPara() {
	if amtScanner.Scan() {
		line := amtScanner.Text()
		if len(line) < 11 {
			line += strings.Repeat(" ", 11-len(line))
		} else if len(line) > 11 {
			line = line[:11]
		}
		acct := line[0:4]
		amtStr := line[4:11]
		var n int64 = 0
		for i := 0; i < len(amtStr); i++ {
			c := amtStr[i]
			if c >= '0' && c <= '9' {
				n = n*10 + int64(c-'0')
			} else if c == ' ' {
				n = n * 10
			} else {
				n = n * 10
			}
		}
		AmtRecData.ArAcct = acct
		AmtRecData.ArAmt = decimal.New(n, -2)
	} else {
		if err := amtScanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	sumBig := WsBigTotal.Add(AmtRecData.ArAmt)
	WsBigTotal = wrapDecimal(sumBig, 7, 2)
	WsWrapTotal = wrapDecimal(WsBigTotal, 5, 2)
	sumSafe := WsSafeTotal.Add(AmtRecData.ArAmt)
	limit := decimal.New(1, 5)
	if sumSafe.Cmp(limit) >= 0 || sumSafe.IsNegative() {
		OverflowPara()
	} else {
		WsSafeTotal = sumSafe.Truncate(2)
	}
	WsCount = (WsCount + 1) % 100
	WsHalf = computeHalf(AmtRecData.ArAmt)
	WsAmtEd = formatEdited(AmtRecData.ArAmt, "ZZ,ZZ9.99")
	WsWrapEd = formatEdited(WsWrapTotal, "ZZ,ZZ9.99")
	WsSafeEd = formatEdited(WsSafeTotal, "ZZ,ZZ9.99")
	WsHalfEd = formatEdited(WsHalf, "ZZ,ZZ9.9")
	acct := AmtRecData.ArAcct
	if len(acct) < 4 {
		acct += strings.Repeat(" ", 4-len(acct))
	} else if len(acct) > 4 {
		acct = acct[:4]
	}
	fmt.Printf("%s %s %s %s %s\n", acct, WsAmtEd, WsWrapEd, WsSafeEd, WsHalfEd)
	ReadPara()
}

func SummaryPara() {
	fmt.Printf("RECORDS: %02d\n", WsCount)
	fmt.Printf("OVERFLOWS: %02d\n", WsOverflows)
}

func OverflowPara() {
	WsOverflows = (WsOverflows + 1) % 100
}

func main() {
	MainPara()
}
